spec.expr:
max(((
  100 * sonic_crm_resource_used{job="$job",instance="$instance"}
  / clamp_min(sonic_crm_resource_used{job="$job",instance="$instance"} + sonic_crm_resource_available{job="$job",instance="$instance"}, 1)
)
and on(job, instance, resource)
((sonic_crm_resource_used{job="$job",instance="$instance"} + sonic_crm_resource_available{job="$job",instance="$instance"}) > 0)) or ((
  100 * sonic_crm_acl_resource_used{job="$job",instance="$instance"}
  / clamp_min(sonic_crm_acl_resource_used{job="$job",instance="$instance"} + sonic_crm_acl_resource_available{job="$job",instance="$instance"}, 1)
)
and on(job, instance, acl_target, resource)
((sonic_crm_acl_resource_used{job="$job",instance="$instance"} + sonic_crm_acl_resource_available{job="$job",instance="$instance"}) > 0))) or vector(0)

(
  2 * sonic_interface_admin_status{job="$job",instance="$instance"}
  + sonic_interface_operational_status{job="$job",instance="$instance"}
)
* on(job, instance, device)
  group_left(alias, description, index)
  sonic_interface_info{job="$job",instance="$instance"}

topk(12,
  (
    (8 * rate(sonic_interface_receive_bytes_total{job="$job",instance="$instance"}[$__rate_interval]))
    * on(job, instance, device) group_left(alias, description) sonic_interface_info{job="$job",instance="$instance"}
  )
  and on(job, instance, device) (rate(sonic_interface_receive_bytes_total{job="$job",instance="$instance"}[$__rate_interval]) > 0)
  and on(job, instance, device) (sonic_interface_speed_bytes{job="$job",instance="$instance"} > 0)
  and on(job, instance, device)
    (rate(sonic_interface_receive_bytes_total{job="$job",instance="$instance"}[$__rate_interval]) <= on(job, instance, device) (sonic_interface_speed_bytes{job="$job",instance="$instance"} * 1.05))
)

